package com.recgombak.batterymonitor;
import android.Manifest;import android.app.*;import android.content.*;import android.content.pm.PackageManager;import android.graphics.*;import android.media.*;import android.net.Uri;import android.net.wifi.WifiManager;import android.os.*;import android.provider.Settings;import android.view.*;import android.widget.*;import org.json.JSONObject;import java.net.*;import java.nio.charset.StandardCharsets;import java.text.SimpleDateFormat;import java.util.*;
public class MainActivity extends Activity{
 private final Handler ui=new Handler(Looper.getMainLooper());private final Map<String,DeviceInfo> devices=Collections.synchronizedMap(new HashMap<>());private final Set<String>lowAlerted=new HashSet<>(),chargeAlerted=new HashSet<>();private final Map<String,Long>chargeLastAlarm=new HashMap<>();private LinearLayout root,list;private TextView subtitle,selfStatus;private volatile boolean listening;private DatagramSocket socket;private WifiManager.MulticastLock lock;
 @Override protected void onCreate(Bundle b){super.onCreate(b);if(Build.VERSION.SDK_INT>=33&&checkSelfPermission(Manifest.permission.POST_NOTIFICATIONS)!=PackageManager.PERMISSION_GRANTED)requestPermissions(new String[]{Manifest.permission.POST_NOTIFICATIONS},44);if(Prefs.getRole(this).isEmpty())chooseRole();else launch();}
 private void chooseRole(){new AlertDialog.Builder(this).setTitle("Pilih mod peranti").setMessage("MONITOR untuk telefon cikgu. TABLET untuk tablet murid.").setCancelable(false).setPositiveButton("MONITOR",(d,w)->{Prefs.setRole(this,"monitor");launch();}).setNegativeButton("TABLET",(d,w)->{Prefs.setRole(this,"tablet");launch();}).show();}
 private void launch(){if("monitor".equals(Prefs.getRole(this)))for(Map.Entry<String,DeviceInfo>e:Prefs.loadKnownDevices(this).entrySet())if(!Prefs.getHidden(this).contains(e.getKey()))devices.put(e.getKey(),e.getValue());buildUi();if(Prefs.isEnabled(this))startBatteryService();if("monitor".equals(Prefs.getRole(this)))startListener();ui.post(refresh);}
 private void buildUi(){ScrollView s=new ScrollView(this);root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setPadding(dp(12),dp(12),dp(12),dp(18));root.setBackgroundColor(Color.rgb(247,248,250));s.addView(root);root.addView(tv("REC Battery Monitor",25,Color.rgb(15,23,42),true));root.addView(tv("Mod "+Prefs.getRole(this).toUpperCase(),12,Color.DKGRAY,true));if("monitor".equals(Prefs.getRole(this)))buildMonitor();else buildTablet();TextView f=tv("Developed by cigunofal",11,Color.GRAY,true);f.setGravity(Gravity.CENTER);root.addView(f);setContentView(s);}
 private void buildTablet(){LinearLayout c=card();c.addView(tv("TABLET INI",11,Color.GRAY,true));TextView name=tv(Prefs.getName(this),22,Color.rgb(15,23,42),true);c.addView(name);Button rename=smallButton("Tukar nama");rename.setOnClickListener(v->rename(name));c.addView(rename);selfStatus=tv("Pemantauan aktif",15,Color.rgb(22,120,60),true);c.addView(selfStatus);root.addView(c);Button overlay=button("Benarkan paparan MASA TAMAT atas app lain");overlay.setOnClickListener(v->openOverlaySettings());root.addView(overlay);Button bg=button("Benarkan berjalan di background");bg.setOnClickListener(v->openBatterySettings());root.addView(bg);}
 private void buildMonitor(){subtitle=tv("Memuatkan rekod tablet…",13,Color.DKGRAY,false);root.addView(subtitle);LinearLayout a=new LinearLayout(this);Button ref=button("↻ Refresh Semua");ref.setOnClickListener(v->sendSimpleCommand("ALL","refresh",0));a.addView(ref,new LinearLayout.LayoutParams(0,-2,1));Button arrange=button("↕ Susunan");arrange.setOnClickListener(v->arrangeDialog());a.addView(arrange,new LinearLayout.LayoutParams(0,-2,1));root.addView(a);LinearLayout tools=new LinearLayout(this);Button settings=button("⚙ Tetapan Monitor");settings.setOnClickListener(v->settingsDialog());tools.addView(settings,new LinearLayout.LayoutParams(0,-2,1));Button manage=button("🗂 Urus Tablet");manage.setOnClickListener(v->DeviceManagerDialog.show(this,devices,id->{devices.remove(id);lowAlerted.remove(id);chargeAlerted.remove(id);chargeLastAlarm.remove(id);render();}));tools.addView(manage,new LinearLayout.LayoutParams(0,-2,1));root.addView(tools);list=new LinearLayout(this);list.setOrientation(LinearLayout.VERTICAL);root.addView(list);}
 private void arrangeDialog(){String[] labels={"Nama A → Z","Bateri terendah → tertinggi","Bateri tertinggi → terendah","Sedang dicas dahulu","Tidak dicas dahulu","Online dahulu","Offline dahulu"};String[] vals={"name","battery_low","battery_high","charging","not_charging","online","offline"};int checked=Math.max(0,Arrays.asList(vals).indexOf(Prefs.getSortMode(this)));new AlertDialog.Builder(this).setTitle("Susun tablet").setSingleChoiceItems(labels,checked,(d,w)->{Prefs.setSortMode(this,vals[w]);d.dismiss();render();}).show();}
 private void settingsDialog(){LinearLayout b=new LinearLayout(this);b.setOrientation(LinearLayout.VERTICAL);EditText low=num(""+Prefs.getThreshold(this));b.addView(label("Amaran bateri rendah pada / bawah (%)"));b.addView(low);EditText full=num(""+Prefs.getChargeThreshold(this));b.addView(label("Amaran ketika dicas mencapai / melebihi (%)"));b.addView(full);b.addView(label("Penggera cas berbunyi di"));RadioGroup dest=new RadioGroup(this);RadioButton monitorOnly=new RadioButton(this);monitorOnly.setText("Monitor sahaja");RadioButton both=new RadioButton(this);both.setText("Monitor + tablet tersebut");dest.addView(monitorOnly);dest.addView(both);if(Prefs.chargeAlarmOnTablet(this))both.setChecked(true);else monitorOnly.setChecked(true);b.addView(dest);CheckBox once=new CheckBox(this);once.setText("Penggera cas berbunyi sekali sahaja");once.setChecked(Prefs.chargeAlarmOnce(this));b.addView(once);b.addView(tv("Jika 'Monitor + tablet' dipilih, tablet yang mencapai had cas turut berbunyi. Mod sekali sahaja aktif semula selepas charger dicabut atau bateri turun bawah had.",11,Color.GRAY,false));EditText in=num(""+Prefs.getInterval(this));b.addView(label("Kemas kini setiap (saat, minimum 5)"));b.addView(in);EditText al=num(""+Prefs.getAlarmSeconds(this));b.addView(label("Tempoh bunyi penggera (saat, 1–60)"));b.addView(al);CheckBox sch=new CheckBox(this);sch.setText("Gunakan jadual pemantauan untuk SEMUA tablet");sch.setChecked(Prefs.scheduleOn(this));b.addView(sch);final int[] times={Prefs.getStartMin(this),Prefs.getEndMin(this)};Button st=button("Mula: "+timeText(times[0])),en=button("Tamat: "+timeText(times[1]));st.setOnClickListener(v->pickTime(times,0,st,"Mula: "));en.setOnClickListener(v->pickTime(times,1,en,"Tamat: "));b.addView(st);b.addView(en);new AlertDialog.Builder(this).setTitle("Tetapan Monitor").setView(b).setPositiveButton("Simpan",(d,w)->{try{Prefs.setThreshold(this,Integer.parseInt(low.getText().toString()));Prefs.setChargeThreshold(this,Integer.parseInt(full.getText().toString()));Prefs.setInterval(this,Integer.parseInt(in.getText().toString()));Prefs.setAlarmSeconds(this,Integer.parseInt(al.getText().toString()));}catch(Exception ignored){}Prefs.setChargeAlarmOnTablet(this,both.isChecked());Prefs.setChargeAlarmOnce(this,once.isChecked());Prefs.setScheduleOn(this,sch.isChecked());Prefs.setSchedule(this,times[0],times[1]);lowAlerted.clear();chargeAlerted.clear();chargeLastAlarm.clear();sendSchedule(sch.isChecked(),times[0],times[1]);}).setNegativeButton("Batal",null).show();}
 private void listen(){try{socket=new DatagramSocket(null);socket.setReuseAddress(true);socket.setBroadcast(true);socket.bind(new InetSocketAddress(BatteryBroadcastService.PORT));socket.setSoTimeout(3000);byte[] buf=new byte[2048];while(listening){try{DatagramPacket p=new DatagramPacket(buf,buf.length);socket.receive(p);JSONObject o=new JSONObject(new String(p.getData(),p.getOffset(),p.getLength(),StandardCharsets.UTF_8));if(!o.optString("app").startsWith("REC_BATTERY_V"))continue;String id=o.optString("id");if(id.isEmpty()||id.equals(Prefs.getId(this))||Prefs.getHidden(this).contains(id))continue;DeviceInfo d=devices.get(id);if(d==null)d=new DeviceInfo();d.id=id;d.name=o.optString("name",d.name==null?"Tablet":d.name);d.model=o.optString("model",d.model==null?"Android":d.model);d.ip=p.getAddress().getHostAddress();d.battery=o.optInt("battery",d.battery);d.charging=o.optBoolean("charging",false);d.timerEnd=o.optLong("timerEnd",d.timerEnd);d.timerDone=o.optBoolean("timerDone",d.timerDone);d.lastSeen=System.currentTimeMillis();devices.put(id,d);Prefs.saveKnownDevices(this,devices);}catch(Exception ignored){}}}catch(Exception ignored){}}
 private void render(){if(list==null)return;long now=System.currentTimeMillis();List<DeviceInfo> data=new ArrayList<>(devices.values());sort(data,now);list.removeAllViews();int low=Prefs.getThreshold(this),high=Prefs.getChargeThreshold(this),online=0;for(DeviceInfo d:data)if(now-d.lastSeen<60000)online++;subtitle.setText(online+" online • "+data.size()+" berdaftar • rendah ≤ "+low+"% • cas ≥ "+high+"%");for(DeviceInfo d:data){boolean on=now-d.lastSeen<60000;long age=now-d.lastSeen;if(on&&d.battery>=0&&d.battery<=low&&!d.charging){if(lowAlerted.add(d.id))alarm("Bateri rendah",d);}else lowAlerted.remove(d.id);if(on&&d.charging&&d.battery>=high){if(Prefs.chargeAlarmOnce(this)){if(chargeAlerted.add(d.id)){alarm("Cas sudah "+high+"%",d);if(Prefs.chargeAlarmOnTablet(this))sendChargeAlarm(d,high);}}else{long last=chargeLastAlarm.containsKey(d.id)?chargeLastAlarm.get(d.id):0L;if(now-last>=60000){chargeLastAlarm.put(d.id,now);alarm("Cas masih melebihi "+high+"%",d);if(Prefs.chargeAlarmOnTablet(this))sendChargeAlarm(d,high);}}}else{chargeAlerted.remove(d.id);chargeLastAlarm.remove(d.id);}LinearLayout c=card();LinearLayout top=new LinearLayout(this);top.setGravity(Gravity.CENTER_VERTICAL);LinearLayout l=new LinearLayout(this);l.setOrientation(LinearLayout.VERTICAL);l.addView(tv(d.name,18,Color.rgb(15,23,42),true));l.addView(tv(d.model,10,Color.GRAY,false));top.addView(l,new LinearLayout.LayoutParams(0,-2,1));Button t=timerButton(d.timerDone?"Hapus Tamat":d.timerEnd>now?"Batal":"Timer");t.setEnabled(on);t.setOnClickListener(v->{if(d.timerDone||d.timerEnd>System.currentTimeMillis())sendSimpleCommand(d.id,"clearTimer",0);else timerDialog(d);});top.addView(t);int bc=!on?Color.GRAY:d.battery<=20?Color.RED:d.battery<=40?Color.rgb(217,119,6):Color.rgb(22,163,74);TextView batt=tv((d.battery<0?"--":d.battery)+"%",26,bc,true);LinearLayout.LayoutParams bp=new LinearLayout.LayoutParams(-2,-2);bp.setMargins(dp(8),0,0,0);batt.setLayoutParams(bp);top.addView(batt);c.addView(top);String st;int sc;if(!on){st=(age>=3600000?"KEMUNGKINAN OFF • ":"")+"Last update: "+lastUpdate(d.lastSeen);sc=Color.GRAY;}else if(d.charging){st="⚡ SEDANG DICAS • ONLINE";sc=Color.rgb(22,163,74);}else{st="● ONLINE";sc=Color.rgb(22,163,74);}if(d.timerDone){st+=" • ⛔ MASA TAMAT";sc=Color.RED;}else if(d.timerEnd>now)st+=" • ⏱ "+formatDuration(d.timerEnd-now);c.addView(tv(st,11,sc,true));list.addView(c);}if(data.isEmpty()){LinearLayout c=card();c.addView(tv("Belum ada tablet berdaftar",16,Color.DKGRAY,true));list.addView(c);}}
 private void sort(List<DeviceInfo>d,long now){String m=Prefs.getSortMode(this);Comparator<DeviceInfo> c;switch(m){case"battery_low":c=Comparator.comparingInt(x->x.battery<0?101:x.battery);break;case"battery_high":c=(x,y)->Integer.compare(y.battery,x.battery);break;case"charging":c=Comparator.comparing((DeviceInfo x)->!x.charging).thenComparing(x->x.name,String.CASE_INSENSITIVE_ORDER);break;case"not_charging":c=Comparator.comparing((DeviceInfo x)->x.charging).thenComparing(x->x.name,String.CASE_INSENSITIVE_ORDER);break;case"online":c=Comparator.comparing((DeviceInfo x)->now-x.lastSeen>=60000).thenComparing(x->x.name,String.CASE_INSENSITIVE_ORDER);break;case"offline":c=Comparator.comparing((DeviceInfo x)->now-x.lastSeen<60000).thenComparing(x->x.name,String.CASE_INSENSITIVE_ORDER);break;default:c=Comparator.comparing(x->x.name==null?"":x.name,String.CASE_INSENSITIVE_ORDER);}d.sort(c);}
 private String lastUpdate(long t){if(t<=0)return"tiada rekod";return new SimpleDateFormat("dd/MM/yyyy h:mm:ss a",Locale.getDefault()).format(new Date(t));}
 private void alarm(String reason,DeviceInfo d){Toast.makeText(this,reason+": "+d.name+" "+d.battery+"%",Toast.LENGTH_LONG).show();int ms=Prefs.getAlarmSeconds(this)*1000;new Thread(()->{ToneGenerator tg=null;try{AudioManager am=(AudioManager)getSystemService(AUDIO_SERVICE);am.setStreamVolume(AudioManager.STREAM_ALARM,am.getStreamMaxVolume(AudioManager.STREAM_ALARM),0);tg=new ToneGenerator(AudioManager.STREAM_ALARM,100);long until=System.currentTimeMillis()+ms;while(System.currentTimeMillis()<until){tg.startTone(ToneGenerator.TONE_CDMA_ALERT_CALL_GUARD,900);Thread.sleep(1000);}}catch(Exception ignored){}finally{if(tg!=null)tg.release();}}).start();}
 private void sendChargeAlarm(DeviceInfo d,int threshold){new Thread(()->{try{JSONObject o=new JSONObject();o.put("app","REC_BATTERY_V9");o.put("target",d.id);o.put("cmd","chargeAlarm");o.put("battery",d.battery);o.put("threshold",threshold);o.put("seconds",Prefs.getAlarmSeconds(this));byte[] data=o.toString().getBytes(StandardCharsets.UTF_8);try(DatagramSocket s=new DatagramSocket()){s.setBroadcast(true);DatagramPacket p=new DatagramPacket(data,data.length,InetAddress.getByName("255.255.255.255"),BatteryBroadcastService.PORT+1);for(int x=0;x<3;x++){s.send(p);Thread.sleep(120);}}}catch(Exception ignored){}}).start();}
 private void timerDialog(DeviceInfo d){EditText e=num("");e.setHint("Minit");new AlertDialog.Builder(this).setTitle("Timer • "+d.name).setView(e).setPositiveButton("Mula",(x,w)->{try{sendSimpleCommand(d.id,"timer",Integer.parseInt(e.getText().toString()));}catch(Exception ignored){}}).setNegativeButton("Batal",null).show();}
 private void startListener(){if(listening)return;listening=true;try{WifiManager w=(WifiManager)getApplicationContext().getSystemService(Context.WIFI_SERVICE);lock=w.createMulticastLock("recBatteryLock");lock.setReferenceCounted(false);lock.acquire();}catch(Exception ignored){}new Thread(this::listen).start();}private void startBatteryService(){Intent i=new Intent(this,BatteryBroadcastService.class);try{if(Build.VERSION.SDK_INT>=26)startForegroundService(i);else startService(i);}catch(Exception ignored){}}
 private void sendSimpleCommand(String target,String cmd,int minutes){sendPacket(target,cmd,minutes,false,0,0);}private void sendSchedule(boolean e,int s,int n){sendPacket("ALL","schedule",0,e,s,n);}private void sendPacket(String target,String cmd,int minutes,boolean enabled,int start,int end){new Thread(()->{try{JSONObject o=new JSONObject();o.put("app","REC_BATTERY_V9");o.put("target",target);o.put("cmd",cmd);if(minutes>0)o.put("minutes",minutes);if("schedule".equals(cmd)){o.put("enabled",enabled);o.put("startMin",start);o.put("endMin",end);}byte[] d=o.toString().getBytes(StandardCharsets.UTF_8);try(DatagramSocket s=new DatagramSocket()){s.setBroadcast(true);DatagramPacket p=new DatagramPacket(d,d.length,InetAddress.getByName("255.255.255.255"),BatteryBroadcastService.PORT+1);for(int x=0;x<5;x++){s.send(p);Thread.sleep(150);}}}catch(Exception ignored){}}).start();}
 private final Runnable refresh=new Runnable(){public void run(){if("monitor".equals(Prefs.getRole(MainActivity.this)))render();else renderSelf();ui.postDelayed(this,1000);}};private void renderSelf(){if(selfStatus==null)return;long left=Prefs.getTimerEnd(this)-System.currentTimeMillis();if(Prefs.isTimerDone(this)){selfStatus.setText("⛔ MASA TAMAT");selfStatus.setTextColor(Color.RED);}else if(left>0)selfStatus.setText("Pemantauan aktif • Timer "+formatDuration(left));else selfStatus.setText(Prefs.inSchedule(this)?"Pemantauan aktif":"Di luar waktu pemantauan");}
 private void openOverlaySettings(){try{startActivity(new Intent(Settings.ACTION_MANAGE_OVERLAY_PERMISSION,Uri.parse("package:"+getPackageName())));}catch(Exception ignored){}}private void openBatterySettings(){try{startActivity(new Intent(Settings.ACTION_IGNORE_BATTERY_OPTIMIZATION_SETTINGS));}catch(Exception ignored){}}private void rename(TextView v){EditText e=new EditText(this);e.setText(Prefs.getName(this));new AlertDialog.Builder(this).setTitle("Nama tablet").setView(e).setPositiveButton("Simpan",(d,w)->{String n=e.getText().toString().trim();if(!n.isEmpty()){Prefs.setName(this,n);v.setText(n);}}).setNegativeButton("Batal",null).show();}
 private EditText num(String s){EditText e=new EditText(this);e.setInputType(2);e.setText(s);return e;}private TextView label(String s){return tv(s,12,Color.DKGRAY,true);}private void pickTime(int[]a,int i,Button b,String p){int m=a[i];new TimePickerDialog(this,(v,h,n)->{a[i]=h*60+n;b.setText(p+timeText(a[i]));},m/60,m%60,false).show();}private String timeText(int m){int h=m/60,n=m%60;String ap=h>=12?"PM":"AM";int hh=h%12;if(hh==0)hh=12;return String.format(Locale.US,"%d:%02d %s",hh,n,ap);}private String formatDuration(long ms){long s=Math.max(0,ms/1000);return String.format(Locale.US,"%02d:%02d",s/60,s%60);}
 private LinearLayout card(){LinearLayout c=new LinearLayout(this);c.setOrientation(LinearLayout.VERTICAL);c.setPadding(dp(11),dp(8),dp(11),dp(8));android.graphics.drawable.GradientDrawable bg=new android.graphics.drawable.GradientDrawable();bg.setColor(Color.WHITE);bg.setCornerRadius(dp(12));bg.setStroke(dp(1),Color.LTGRAY);c.setBackground(bg);LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.setMargins(0,dp(4),0,dp(3));c.setLayoutParams(lp);return c;}private TextView tv(String t,int s,int col,boolean bold){TextView v=new TextView(this);v.setText(t);v.setTextSize(s);v.setTextColor(col);if(bold)v.setTypeface(Typeface.DEFAULT,Typeface.BOLD);return v;}private Button button(String t){Button b=new Button(this);b.setText(t);b.setAllCaps(false);return b;}private Button smallButton(String t){Button b=button(t);b.setTextSize(10);b.setMinHeight(0);b.setMinimumHeight(0);b.setMinWidth(0);b.setMinimumWidth(0);b.setPadding(dp(9),dp(2),dp(9),dp(2));return b;}private Button timerButton(String t){Button b=button(t);b.setTextSize(12);b.setMinHeight(dp(38));b.setMinimumHeight(dp(38));b.setPadding(dp(12),dp(4),dp(12),dp(4));return b;}private int dp(int v){return(int)(v*getResources().getDisplayMetrics().density+.5f);}
 @Override protected void onDestroy(){if("monitor".equals(Prefs.getRole(this)))Prefs.saveKnownDevices(this,devices);listening=false;ui.removeCallbacks(refresh);if(socket!=null)socket.close();if(lock!=null&&lock.isHeld())lock.release();super.onDestroy();}
}
